<body>
<div class="app">
  <header class="topbar">
    <div class="intro">
      <div class="eyebrow">二次函数 · 值域实验台</div>
      <h1>看见 <span class="math-inline">y = −x<sup>2</sup> + 2x − 14</span> 的值域</h1>
      <p class="subtitle">先沿着曲线看高度怎样变化，再把“最高位置”从式子里找出来，最后扫描每一个可能的高度。</p>
    </div>
    <div class="problem-card">
      <div class="problem-tag">题目</div>
      <div class="problem-text">
        函数 <span class="math-inline">y = −x<sup>2</sup> + 2x − 14</span> 的值域是
        <span class="blank">？</span>
      </div>
    </div>
  </header>

  <main class="workspace">
    <section class="panel graph-panel">
      <div class="graph-head">
        <div>
          <div class="mini-label">当前图形</div>
          <h2 id="stateTitle">看整条曲线</h2>
        </div>
        <div class="step-pills" id="stepPills">
          <button type="button" class="step-pill active" data-state="1"><span>1</span>看曲线</button>
          <button type="button" class="step-pill" data-state="2"><span>2</span>找顶点</button>
          <button type="button" class="step-pill" data-state="3"><span>3</span>高度上限</button>
          <button type="button" class="step-pill" data-state="4"><span>4</span>扫描高度</button>
        </div>
      </div>

      <div class="svg-shell">
        <svg id="board" viewBox="0 0 960 620" role="img" aria-label="二次函数图像与值域扫描图">
          <defs>
            <clipPath id="plotClip">
              <rect x="90" y="55" width="780" height="500"></rect>
            </clipPath>
            <marker id="arrowAxis" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
              <path d="M0 0 L10 5 L0 10 Z" fill="#56616f"></path>
            </marker>
            <marker id="arrowGreen" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="8" markerHeight="8" orient="auto-start-reverse">
              <path d="M0 0 L10 5 L0 10 Z" fill="#059669"></path>
            </marker>
          </defs>

          <rect class="plot-bg" x="90" y="55" width="780" height="500" rx="16"></rect>

          <g id="rangeLayer" class="is-hidden">
            <rect id="rangeShade" class="range-shade" x="90" y="275" width="780" height="280"></rect>
            <line id="rangeLine" class="range-line" x1="910" y1="275" x2="910" y2="531" marker-end="url(#arrowGreen)"></line>
            <line id="rangeTickTop" class="range-tick" x1="898" y1="275" x2="922" y2="275"></line>
            <text id="rangeTitle" class="range-label" x="910" y="260" text-anchor="middle">值域</text>
            <text id="rangeLabel13" class="range-label" x="928" y="280" text-anchor="start">−13</text>
            <text id="rangeLabelInf" class="range-label" x="928" y="537" text-anchor="start">−∞</text>
          </g>

          <g id="gridLayer"></g>
          <g id="axisLayer"></g>

          <g clip-path="url(#plotClip)">
            <path id="curveHalo" class="curve-halo"></path>
            <path id="curvePath" class="curve-line"></path>
          </g>

          <g id="maxLineLayer" class="is-hidden">
            <line id="maxLine" class="max-line" x1="90" y1="275" x2="870" y2="275"></line>
            <text id="maxLineLabel" class="max-label" x="858" y="263" text-anchor="end">最高高度 y = −13</text>
          </g>

          <g id="vertexLayer" class="is-hidden">
            <line id="symAxis" class="sym-axis" x1="480" y1="55" x2="480" y2="555"></line>
            <circle id="vertexDot" class="vertex-dot" cx="480" cy="275" r="7"></circle>
            <text id="vertexLabel" class="vertex-label" x="494" y="263">顶点 (1, −13)</text>
            <text id="symLabel" class="note-label" x="488" y="79">对称轴 x = 1</text>
          </g>

          <g id="scanLayer" class="is-hidden">
            <line id="scanLine" class="scan-line" x1="90" y1="400" x2="870" y2="400"></line>
            <circle id="scanDotL" class="scan-dot" cx="250" cy="400" r="6"></circle>
            <circle id="scanDotR" class="scan-dot" cx="650" cy="400" r="6"></circle>
            <text id="scanLabel" class="scan-label" x="858" y="390" text-anchor="end"></text>
            <text id="scanTangentLabel" class="scan-label" x="496" y="303" text-anchor="start"></text>
          </g>

          <g id="pointLayer">
            <line id="projH" class="proj-line" x1="650" y1="330" x2="387" y2="330"></line>
            <line id="projV" class="proj-line" x1="650" y1="330" x2="650" y2="84"></line>
            <circle id="axisDot" class="proj-axis-dot" cx="387" cy="330" r="5"></circle>
            <circle id="xAxisDot" class="proj-axis-dot" cx="650" cy="84" r="4"></circle>
            <circle id="pointRing" class="point-ring" cx="650" cy="330" r="15"></circle>
            <circle id="pointDot" class="point-dot" cx="650" cy="330" r="7"></circle>
            <text id="pointLabel" class="point-label" x="662" y="318">P</text>
            <text id="projYLabel" class="proj-label" x="397" y="322"></text>
          </g>
        </svg>
      </div>

      <div class="control-deck">
        <div class="slider-group" id="xControl">
          <div class="control-head">
            <label for="xSlider">动点横坐标 <span class="math-chip">x</span></label>
            <span class="control-hint">滑块只演示显示范围</span>
          </div>
          <input id="xSlider" type="range" min="-3.2" max="5.2" step="0.01" value="3">
          <div class="readout" id="xReadout">x = 3.00　y = −17.00</div>
        </div>

        <div class="slider-group is-hidden" id="yControl">
          <div class="control-head">
            <label for="ySlider">扫描高度 <span class="math-chip">y</span></label>
            <span class="control-hint">演示区间 −30 到 −13</span>
          </div>
          <input id="ySlider" type="range" min="-30" max="-13" step="0.1" value="-20">
          <div class="readout" id="yReadout">y = −20.0：交点 x₁ = −1.65，x₂ = 3.65</div>
        </div>

        <div class="action-row">
          <button type="button" class="primary" id="playBtn">播放</button>
          <button type="button" class="ghost" id="keyBtn">到最高处</button>
        </div>
      </div>
    </section>

    <aside class="side">
      <section class="panel explanation">
        <div class="step-label" id="stepLabel">步骤 1 / 4 · 观察</div>
        <h2 id="explainTitle">整条曲线在说什么？</h2>
        <div class="explain-body" id="explainBody"></div>
        <div class="formula-box" id="formulaBox"></div>
      </section>

      <div class="side-nav">
        <button type="button" class="ghost" id="prevBtn">上一步</button>
        <button type="button" class="primary" id="nextBtn">下一步</button>
      </div>

      <section class="panel answer-panel is-hidden" id="answerPanel">
        <div class="answer-kicker">值域的完整写法</div>
        <div class="answer-value">(−∞, −13]</div>
        <div class="answer-note">最大值 −13 在 x = 1 取得；向下没有最小值。</div>
      </section>
    </aside>
  </main>

  <footer class="footnote">
    主图按函数图像的显示范围绘制，横、纵轴单位长度不同；x 滑块只覆盖显示范围 −3.2 到 5.2，而函数本身对所有实数 x 都有定义。扫描高度只演示 −30 到 −13，抛物线还会继续向下无限延伸。
  </footer>
</div>

<script>
  const NS = "http://www.w3.org/2000/svg";
  const XMIN = -3.2, XMAX = 5.2, YMIN = -32, YMAX = 2;
  const L = 90, R = 870, T = 55, B = 555;

  const sx = x => L + (x - XMIN) / (XMAX - XMIN) * (R - L);
  const sy = y => T + (YMAX - y) / (YMAX - YMIN) * (B - T);
  const f = x => -x * x + 2 * x - 14;

  const $ = id => document.getElementById(id);

  let state = 1;
  let currentX = 3;
  let scanY = -20;
  let playing = false;
  let raf = null;

  function fmt(n, d = 2) {
    const v = Math.abs(n).toFixed(d);
    return (n < 0 ? "−" : "") + v;
  }

  function setAttrs(el, attrs) {
    for (const key in attrs) {
      el.setAttribute(key, attrs[key]);
    }
  }

  function svgNode(tag, attrs = {}, text = null) {
    const node = document.createElementNS(NS, tag);
    setAttrs(node, attrs);
    if (text !== null) node.textContent = text;
    return node;
  }

  function addTo(parent, tag, attrs = {}, text = null) {
    const node = svgNode(tag, attrs, text);
    parent.appendChild(node);
    return node;
  }

  function drawStatic() {
    let d = "";
    const step = 0.035;
    for (let x = XMIN; x <= XMAX + 1e-9; x += step) {
      const px = sx(x);
      const py = sy(f(x));
      d += (d === "" ? "M" : " L") + px.toFixed(2) + " " + py.toFixed(2);
    }
    $("curvePath").setAttribute("d", d);
    $("curveHalo").setAttribute("d", d);

    const maxY = sy(-13);

    setAttrs($("maxLine"), { x1: L, y1: maxY, x2: R, y2: maxY });
    setAttrs($("maxLineLabel"), { x: R - 12, y: maxY - 12 });

    setAttrs($("rangeShade"), {
      x: L,
      y: maxY,
      width: R - L,
      height: B - maxY
    });
    setAttrs($("rangeLine"), {
      x1: 910,
      y1: maxY,
      x2: 910,
      y2: B - 24
    });
    setAttrs($("rangeTickTop"), {
      x1: 898,
      y1: maxY,
      x2: 922,
      y2: maxY
    });
    setAttrs($("rangeTitle"), { x: 910, y: maxY - 13 });
    setAttrs($("rangeLabel13"), { x: 928, y: maxY + 5 });
    setAttrs($("rangeLabelInf"), { x: 928, y: B - 18 });

    const vx = sx(1);
    const vy = sy(-13);
    setAttrs($("vertexDot"), { cx: vx, cy: vy });
    setAttrs($("vertexLabel"), { x: vx + 14, y: vy - 12 });
    setAttrs($("symAxis"), { x1: vx, y1: T, x2: vx, y2: B });
    setAttrs($("symLabel"), { x: vx + 8, y: T + 24 });

    const grid = $("gridLayer");
    grid.innerHTML = "";

    for (let x = -3; x <= 5; x++) {
      addTo(grid, "line", {
        x1: sx(x),
        y1: T,
        x2: sx(x),
        y2: B,
        class: "grid-line"
      });
    }

    for (let y = -30; y <= 0; y += 5) {
      addTo(grid, "line", {
        x1: L,
        y1: sy(y),
        x2: R,
        y2: sy(y),
        class: "grid-line"
      });
    }

    const axis = $("axisLayer");
    axis.innerHTML = "";

    addTo(axis, "line", {
      x1: L,
      y1: sy(0),
      x2: R + 9,
      y2: sy(0),
      class: "axis-line",
      "marker-end": "url(#arrowAxis)"
    });

    addTo(axis, "line", {
      x1: sx(0),
      y1: B,
      x2: sx(0),
      y2: T - 9,
      class: "axis-line",
      "marker-end": "url(#arrowAxis)"
    });

    addTo(axis, "text", {
      x: R + 19,
      y: sy(0) + 6,
      class: "axis-name"
    }, "x");

    addTo(axis, "text", {
      x: sx(0) + 12,
      y: T - 8,
      class: "axis-name"
    }, "y");

    for (let x = -3; x <= 5; x++) {
      addTo(axis, "text", {
        x: sx(x),
        y: sy(0) + 24,
        class: "tick-label",
        "text-anchor": "middle"
      }, x === 0 ? "0" : fmt(x, 0));
    }

    for (let y = -5; y >= -30; y -= 5) {
      addTo(axis, "text", {
        x: sx(0) - 10,
        y: sy(y) + 5,
        class: "tick-label",
        "text-anchor": "end"
      }, fmt(y, 0));
    }

    addTo(axis, "text", {
      x: L + 8,
      y: B + 28,
      class: "note-label"
    }, "横、纵轴单位长度不同；图形只显示其中一段范围");
  }

  const stateData = [
    {
      graphTitle: "看整条曲线",
      stage: "观察",
      explainTitle: "整条曲线在说什么？",
      body: `<p>二次项系数是 <b>−1</b>，所以抛物线<b>开口向下</b>。拖动红点 P，比较它在不同位置的高度。</p>
        <div class="cue">观察：高度先升后降，顶点附近出现最高位置。</div>`,
      formula: `<div class="calc-line">原函数：<span class="eq-main">y = −x<sup>2</sup> + 2x − 14</span></div>
        <div class="formula-note">先不急着算：让图形告诉你最高处大概在哪里。</div>`
    },
    {
      graphTitle: "配方找顶点",
      stage: "找最高位置",
      explainTitle: "把“最高点”从式子里找出来",
      body: `<p>配方不改变函数，只把抛物线写成“顶点式”。绿色竖线是对称轴，绿色点是顶点。</p>
        <div class="cue">顶点式里，平方项会直接告诉我们最高高度。</div>`,
      formula: `<div class="calc-line">y = −x<sup>2</sup> + 2x − 14</div>
        <div class="calc-line">　= −(x<sup>2</sup> − 2x) − 14</div>
        <div class="calc-line">　= −[(x − 1)<sup>2</sup> − 1] − 14</div>
        <div class="calc-line strong-line">　= −(x − 1)<sup>2</sup> − 13</div>
        <div class="formula-note">顶点： (1, −13)</div>`
    },
    {
      graphTitle: "高度不会超过 −13",
      stage: "高度上限",
      explainTitle: "平方项给出高度上限",
      body: `<p>平方项 <b>(x−1)<sup>2</sup></b> 最小为 0；前面有负号，所以它让高度“只减不增”。</p>
        <div class="cue">当 x = 1 时，函数达到最高高度 −13。</div>`,
      formula: `<div class="calc-line">(x − 1)<sup>2</sup> ≥ 0</div>
        <div class="calc-line">⇒ −(x − 1)<sup>2</sup> ≤ 0</div>
        <div class="calc-line strong-line">⇒ y = −(x − 1)<sup>2</sup> − 13 ≤ −13</div>
        <div class="formula-note">等号在 x = 1 时取得。</div>`
    },
    {
      graphTitle: "扫描高度，确认没有遗漏",
      stage: "检查完整值域",
      explainTitle: "每个 y ≤ −13 都能取到",
      body: `<p>紫色水平线代表一个高度 y。拖动它：在 −13 以下，水平线与抛物线有两个交点；到 −13 时，只剩顶点。</p>
        <div class="cue">所以 y 不能高于 −13；而 −13 以下的每个高度都能被取到。</div>
        <div class="fine">动画只扫到 −30 是为了看清交点；抛物线还会继续向下无限延伸。</div>`,
      formula: `<div class="calc-line">y = −(x − 1)<sup>2</sup> − 13</div>
        <div class="calc-line">(x − 1)<sup>2</sup> = −13 − y</div>
        <div class="calc-line strong-line">x = 1 ± √(−13 − y)</div>
        <div class="formula-note">当且仅当 y ≤ −13，根号内 ≥ 0，方程有实数解。</div>`
    }
  ];

  function renderGraph() {
    const pointLayer = $("pointLayer");
    const scanLayer = $("scanLayer");

    $("maxLineLayer").classList.toggle("is-hidden", state < 2);
    $("vertexLayer").classList.toggle("is-hidden", state < 2);
    $("rangeLayer").classList.toggle("is-hidden", state < 3);
    scanLayer.classList.toggle("is-hidden", state !== 4);
    pointLayer.classList.toggle("is-hidden", state === 4);

    $("xSlider").value = currentX;
    $("ySlider").value = scanY;

    if (state < 4) {
      const yv = f(currentX);
      const px = sx(currentX);
      const py = sy(yv);
      const axisX = sx(0);
      const axisY0 = sy(0);

      setAttrs($("projH"), { x1: px, y1: py, x2: axisX, y2: py });
      setAttrs($("projV"), { x1: px, y1: py, x2: px, y2: axisY0 });
      setAttrs($("axisDot"), { cx: axisX, cy: py });
      setAttrs($("xAxisDot"), { cx: px, cy: axisY0 });
      setAttrs($("pointRing"), { cx: px, cy: py });
      setAttrs($("pointDot"), { cx: px, cy: py });

      const nearVertex = Math.abs(currentX - 1) < 0.06;
      const anchor = currentX > 4.4 ? "end" : "start";
      const dx = anchor === "end" ? -12 : 12;
      const dy = nearVertex ? 28 : -12;

      setAttrs($("pointLabel"), {
        x: px + dx,
        y: py + dy,
        "text-anchor": anchor
      });
      $("pointLabel").textContent = nearVertex ? "P = 顶点" : "P";

      setAttrs($("projYLabel"), {
        x: axisX + 10,
        y: py - 8,
        "text-anchor": "start"
      });
      $("projYLabel").textContent = "y = " + fmt(yv, 2);

      $("xReadout").innerHTML = `x = ${fmt(currentX, 2)}　y = ${fmt(yv, 2)}`;
    } else {
      const s = Math.sqrt(Math.max(0, -13 - scanY));
      const lineY = sy(scanY);
      const leftX = sx(1 - s);
      const rightX = sx(1 + s);

      setAttrs($("scanLine"), { x1: L, y1: lineY, x2: R, y2: lineY });
      setAttrs($("scanDotL"), { cx: leftX, cy: lineY });
      setAttrs($("scanDotR"), { cx: rightX, cy: lineY });

      $("scanDotR").style.display = s < 0.035 ? "none" : "";
      setAttrs($("scanLabel"), { x: R - 12, y: lineY - 10 });
      $("scanLabel").textContent = "y = " + fmt(scanY, 1);

      if (s < 0.035) {
        $("scanTangentLabel").style.display = "";
        setAttrs($("scanTangentLabel"), {
          x: sx(1) + 16,
          y: lineY + 28,
          "text-anchor": "start"
        });
        $("scanTangentLabel").textContent = "只与顶点相切";
      } else {
        $("scanTangentLabel").style.display = "none";
        $("scanTangentLabel").textContent = "";
      }

      if (s < 0.01) {
        $("yReadout").innerHTML = "y = −13.0：与顶点相切，x = 1";
      } else {
        $("yReadout").innerHTML =
          `y = ${fmt(scanY, 1)}：交点 x<sub>1</sub> = ${fmt(1 - s, 2)}，x<sub>2</sub> = ${fmt(1 + s, 2)}`;
      }
    }
  }

  function renderAll() {
    const data = stateData[state - 1];

    $("stateTitle").textContent = data.graphTitle;
    $("stepLabel").textContent = `步骤 ${state} / 4 · ${data.stage}`;
    $("explainTitle").textContent = data.explainTitle;
    $("explainBody").innerHTML = data.body;
    $("formulaBox").innerHTML = data.formula;

    $("answerPanel").classList.toggle("is-hidden", state !== 4);
    $("prevBtn").disabled = state === 1;
    $("nextBtn").disabled = state === 4;
    $("keyBtn").textContent = state === 4 ? "扫到 −13" : (state === 1 ? "到最高处" : "到顶点");

    document.querySelectorAll(".step-pill").forEach(btn => {
      btn.classList.toggle("active", Number(btn.dataset.state) === state);
    });

    $("xControl").classList.toggle("is-hidden", state === 4);
    $("yControl").classList.toggle("is-hidden", state !== 4);

    renderGraph();
  }

  function stopPlay() {
    playing = false;
    if (raf) {
      cancelAnimationFrame(raf);
      raf = null;
    }
    $("playBtn").textContent = "播放";
  }

  function startPlay() {
    if (playing) return;
    playing = true;
    $("playBtn").textContent = "暂停";

    let last = performance.now();

    function frame(ts) {
      if (!playing) return;
      const dt = Math.min(50, ts - last) / 1000;
      last = ts;

      if (state === 4) {
        scanY += 4.5 * dt;
        if (scanY >= -13) scanY = -13;
        if (scanY <= -30) scanY = -30;
        if (scanY === -13) {
          // bounce after reaching the top
          scanY -= 0.02;
        }
      } else {
        currentX += 1.35 * dt;
        if (currentX >= 4.65) currentX = 4.65;
        if (currentX <= -2.65) currentX = -2.65;
        if (currentX === 4.65) {
          currentX -= 0.02;
        }
      }

      renderGraph();
      raf = requestAnimationFrame(frame);
    }

    raf = requestAnimationFrame(frame);
  }

  function setState(n) {
    if (n < 1 || n > 4) return;
    stopPlay();
    state = n;
    renderAll();
  }

  document.querySelectorAll(".step-pill").forEach(btn => {
    btn.addEventListener("click", () => setState(Number(btn.dataset.state)));
  });

  $("prevBtn").addEventListener("click", () => setState(state - 1));
  $("nextBtn").addEventListener("click", () => setState(state + 1));

  $("xSlider").addEventListener("input", e => {
    stopPlay();
    currentX = parseFloat(e.target.value);
    renderGraph();
  });

  $("ySlider").addEventListener("input", e => {
    stopPlay();
    scanY = parseFloat(e.target.value);
    renderGraph();
  });

  $("playBtn").addEventListener("click", () => {
    if (playing) {
      stopPlay();
    } else {
      startPlay();
    }
  });

  $("keyBtn").addEventListener("click", () => {
    stopPlay();
    if (state === 4) {
      scanY = -13;
    } else {
      currentX = 1;
    }
    renderGraph();
  });

  drawStatic();
  setState(1);
</script>
</body>
</html>
